            transaction.executeWithoutResult(status -> {
                sheetRows.lockById(sheetId);
                claims.find(sheetId, claimId)
                        .filter(c -> c.getStatus() == ClaimStatus.DRAFT && c.getAmount().compareTo(amount) != 0)
